def pick_object(obj_name):
    """Precondition: Gripper is empty and obj_name is visible; Postcondition: obj_name is grasped in gripper."""
    cands = grasp_candidates(obj_name)
    cands = sorted(cands, key=lambda c: c.get("score", 0), reverse=True)
    for cand in cands:
        res = grasp(cand)
        if res.get("holding_something", False):
            return True
    return False

def pick_thin_object(obj_name, min_grasp_height=0.025):
    """Gripper is empty; grasps the object above min_grasp_height to avoid table collision, ending with object held."""
    cands = grasp_candidates(obj_name)
    valid_cands = [c for c in cands if c.get("fits_open_fingers", True)]
    valid_cands.sort(key=lambda c: c.get("score", 0), reverse=True)

    for cand in valid_cands:
        cand_copy = dict(cand)
        if cand_copy.get("height", 0) < min_grasp_height:
            cand_copy["height"] = min_grasp_height
        res = grasp(cand_copy)
        if res.get("holding_something", False):
            return True

    if valid_cands:
        cand_copy = dict(valid_cands[0])
        if cand_copy.get("height", 0) < min_grasp_height:
            cand_copy["height"] = min_grasp_height
        res = grasp(cand_copy)
        return res.get("holding_something", False)
    return False

def pick_object_v2(obj_name):
    """Pre: gripper is empty and obj_name is visible. Post: robot is holding obj_name if a grasp candidate succeeded."""
    cands = grasp_candidates(obj_name)
    cands = sorted(cands, key=lambda c: c.get("score", 0), reverse=True)
    for cand in cands:
        res = grasp(cand)
        if res.get("holding_something", False):
            return True
    return False
